<template><section class="workbench" data-cpf-page="online-runtime-diagnostics"><header class="header"><div><h1>Online Runtime Diagnostics</h1><p>Service·Instance·Queue·Broker·File I/O·Idempotency의 실제 Runtime 상태를 한 화면에서 비교합니다.</p></div><button :disabled="loading" @click="load">새로고침</button></header><form class="filters" @submit.prevent="load"><label>Environment<input v-model.trim="environment"></label><label>Service ID<input v-model.trim="serviceId"></label><label>Transaction ID<input v-model.trim="transactionId"></label><button type="submit">진단</button></form><p v-if="error" class="state error">{{ error }}</p><p v-else-if="loading" class="state">Runtime 진단 데이터를 수집하고 있습니다.</p><div class="cards"><article class="card"><span>Control Health</span><strong>{{ summary(health) }}</strong><small>{{ text(health,'updatedAt','updated_at') }}</small></article><article class="card"><span>Runtime State</span><strong>{{ summary(status) }}</strong><small>{{ serviceId||'ALL SERVICES' }}</small></article><article class="card"><span>Outbox</span><strong>{{ outbox.length }}</strong><small>미전달/재시도 포함</small></article><article class="card"><span>Inbox</span><strong>{{ inbox.length }}</strong><small>중복·처리 상태</small></article><article class="card"><span>Idempotency</span><strong>{{ idempotency.length }}</strong><small>예약·완료·충돌</small></article><article class="card"><span>File I/O</span><strong>{{ files.length }}</strong><small>전송·결과 상태</small></article></div><div class="tabs"><div><button v-for="name in ['runtime','outbox','inbox','idempotency','files']" :key="name" :class="{primary:tab===name}" @click="tab=name">{{ name }}</button></div><span class="muted">Freshness {{ fetchedAt||'-' }}</span></div><pre v-if="tab==='runtime'" class="detail">{{ pretty({health,status}) }}</pre><div v-else class="table-wrap"><table><thead><tr><th>ID/Key</th><th>Status</th><th>Transaction</th><th>Service/Topic</th><th>Updated</th></tr></thead><tbody><tr v-for="(row,index) in activeRows" :key="index"><td>{{ text(row,'id','messageId','message_id','key','transferId','transfer_id') }}</td><td>{{ text(row,'status','state') }}</td><td>{{ text(row,'transactionId','transaction_id') }}</td><td>{{ text(row,'serviceId','service_id','topic','scope','target') }}</td><td>{{ text(row,'updatedAt','updated_at','createdAt','created_at') }}</td></tr></tbody></table></div></section></template>
<script setup lang="ts">import { computed,onMounted,ref } from 'vue';import { findFileTransfers,findIdempotency,findInbox,findOutbox,findRuntimeHealth,findRuntimeStatus,type JsonMap } from './api';import { errorMessage,pretty,text } from './support';const environment=ref(''),serviceId=ref(''),transactionId=ref(''),health=ref<JsonMap>({}),status=ref<JsonMap>({}),outbox=ref<JsonMap[]>([]),inbox=ref<JsonMap[]>([]),idempotency=ref<JsonMap[]>([]),files=ref<JsonMap[]>([]),loading=ref(false),error=ref(''),fetchedAt=ref(''),tab=ref('runtime');const activeRows=computed(()=>tab.value==='outbox'?outbox.value:tab.value==='inbox'?inbox.value:tab.value==='idempotency'?idempotency.value:files.value);function summary(row:JsonMap){return text(row,'status','state','health','overallStatus')}async function load(){loading.value=true;error.value='';try{const result=await Promise.allSettled([findRuntimeHealth(),findRuntimeStatus(environment.value,serviceId.value),findOutbox(undefined,transactionId.value,undefined,100),findInbox(undefined,undefined,100),findIdempotency(undefined,undefined,undefined,100),findFileTransfers(undefined,transactionId.value,100)]);const [a,b,c,d,e,f]=result;if(a.status==='fulfilled')health.value=a.value;if(b.status==='fulfilled')status.value=b.value;if(c.status==='fulfilled')outbox.value=c.value;if(d.status==='fulfilled')inbox.value=d.value;if(e.status==='fulfilled')idempotency.value=e.value;if(f.status==='fulfilled')files.value=f.value;const failures=result.filter(x=>x.status==='rejected');if(failures.length)error.value=`부분 실패 ${failures.length}/6: ${failures.map(x=>x.status==='rejected'?errorMessage(x.reason):'').join(' | ')}`;fetchedAt.value=new Date().toISOString()}finally{loading.value=false}}onMounted(load);</script><style scoped>
.workbench{display:grid;gap:1rem}.header,.actions,.tabs,.pager{display:flex;gap:.65rem;align-items:center;justify-content:space-between;flex-wrap:wrap}.header h1,.header h2{margin:0}.header p{margin:.35rem 0 0;color:#52606d}.filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:.7rem;align-items:end}.filters label,.dialog label{display:grid;gap:.3rem}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:.75rem}.card,.panel{border:1px solid #d7dde5;border-radius:.6rem;padding:1rem;background:#fff}.card strong{font-size:1.35rem;display:block}.table-wrap{overflow:auto;border:1px solid #d7dde5;border-radius:.5rem}table{border-collapse:collapse;width:100%;min-width:900px}th,td{padding:.65rem;border-bottom:1px solid #e4e8ed;text-align:left;vertical-align:top}tbody tr{cursor:pointer}tbody tr:hover,tbody tr.selected{background:#f3f6f9}.state{padding:.75rem;border-radius:.4rem;background:#eef3f7}.state.error{background:#fff0f0;color:#a51d1d}.state.warning{background:#fff8dc;color:#715600}.state.success{background:#edf9f0;color:#126b35}.danger{background:#9d1c1c;color:white}.primary{background:#1f5f99;color:white}.detail{white-space:pre-wrap;overflow:auto;max-height:480px;background:#111827;color:#e5e7eb;padding:1rem;border-radius:.5rem}.dialog-backdrop{position:fixed;inset:0;background:#0008;display:grid;place-items:center;z-index:1000}.dialog{width:min(620px,calc(100vw - 2rem));max-height:90vh;overflow:auto;background:#fff;border-radius:.65rem;padding:1.2rem;display:grid;gap:1rem}.dialog textarea{min-height:100px}.confirm{display:flex!important;grid-template-columns:auto 1fr!important;align-items:center}.muted{color:#68737d}.badge{display:inline-block;padding:.15rem .45rem;border-radius:999px;background:#e9eef5}.links{display:flex;gap:.6rem;flex-wrap:wrap}@media(max-width:720px){.header{display:grid}.actions{justify-content:flex-start}}
</style>